const update = $json;
const message = update.message || update.edited_message || {};
const from = message.from || {};
const chat = message.chat || {};
const messageText = String(update.message_text || message.text || message.caption || '').trim();
const normalizedText = String(update.normalized_text || messageText.toLowerCase().replace(/\s+/g, ' ')).trim();

const lookupPhrases = [
  '/mywarranties',
  'show my warranties',
  'my warranties',
  'my products',
  'show my products'
];

const isLookupIntent = lookupPhrases.some((phrase) => normalizedText === phrase || normalizedText.includes(phrase));
const telegramUserId = update.telegram_user_id || update.user_id || from.id || '';

return [
  {
    json: {
      chat_id: update.chat_id || chat.id,
      telegram_user_id: telegramUserId,
      user_name: update.user_name || [from.first_name, from.last_name].filter(Boolean).join(' ') || from.username || 'Telegram User',
      message_text: messageText,
      normalized_text: normalizedText,
      is_lookup_intent: isLookupIntent
    }
  }
];

const lookup = $node['Detect Lookup Intent'].json;
const telegramUserId = String(lookup.telegram_user_id || '').trim();
const rows = $input.all().map((item) => item.json || {});

const products = rows.filter((row) => {
  const rowUserId = String(row.User_ID || row.user_id || '').trim();
  return rowUserId && rowUserId === telegramUserId;
});

return [
  {
    json: {
      chat_id: lookup.chat_id,
      telegram_user_id: telegramUserId,
      user_name: lookup.user_name,
      products,
      product_count: products.length
    }
  }
];

const products = Array.isArray($json.products) ? $json.products : [];

if (products.length === 0) {
  return [
    {
      json: {
        chat_id: $json.chat_id,
        reply_text: 'No saved warranties found yet. Upload a bill or warranty card first.'
      }
    }
  ];
}

const lines = products.map((product, index) => {
  const productName = product.Product_Name || 'Unnamed product';
  const brand = product.Brand || 'Not found';
  const warrantyValidTill = product.Warranty_Expiry_Date || 'Unknown';
  const warrantyStatus = product.Warranty_Status || 'Unknown';
  const invoiceNumber = product.Invoice_Number || 'Not found';

  return [
    `${index + 1}. ${productName}`,
    `Brand: ${brand}`,
    `Warranty Valid Till: ${warrantyValidTill}`,
    `Warranty Status: ${warrantyStatus}`,
    `Invoice Number: ${invoiceNumber}`
  ].join('\n');
});

const replyText = `Your saved warranties:\n\n${lines.join('\n\n')}`;

return [
  {
    json: {
      chat_id: $json.chat_id,
      reply_text: replyText.length > 3900 ? `${replyText.slice(0, 3850)}\n\nMore products are saved, but this message was shortened.` : replyText
    }
  }
];
